//! Raw FFI bindings generated by bindgen from the xmlsec1/libxml2 headers.
//! Nothing in here is safe to call directly — every call site must uphold
//! libxmlsec1's own invariants (init-before-use, non-null docs/nodes,
//! matching create/destroy pairs, etc). [`crate::dsig`] is the only module
//! that calls into this one; everything *it* exposes is safe.

#![allow(
    non_upper_case_globals,
    non_camel_case_types,
    non_snake_case,
    dead_code,
    clippy::upper_case_acronyms
)]

include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
